    # Function to calculate sum of submatrix from (x1, y1) to (x2, y2)
    def get_sum(x1, y1, x2, y2):
        return prefix_sum[x2][y2] - prefix_sum[x1 - 1][y2] - prefix_sum[x2][y1 - 1] + prefix_sum[x1 - 1][y1 - 1]

    # Iterate over all possible top-left corners of the rectangle
    for x in range(1, n + 1):
        for y in range(x, n + 1):
            # Iterate over all possible bottom-right corners of the rectangle
            for z in range(1, n + 1):
                for t in range(z, n + 1):
                    # Calculate the sum of the current rectangle
                    if get_sum(x, y, z, t) == a:
                        count += 1

    return count

