def count_rectangles_with_sum(a, s):
    n = len(s)
    b = [[0] * n for _ in range(n)]

    # Fill the matrix b with b_{ij} = s_{i} * s_{j}
    for i in range(n):
        for j in range(n):
            b[i][j] = int(s[i]) * int(s[j])

    # This function calculates the sum of elements in the submatrix
    def submatrix_sum(x1, y1, x2, y2):
        return (b[x2][y2] 
                - (b[x1 - 1][y2] if x1 > 0 else 0) 
                - (b[x2][y1 - 1] if y1 > 0 else 0) 
                + (b[x1 - 1][y1 - 1] if x1 > 0 and y1 > 0 else 0))

    count = 0
    # Iterate over all possible top-left and bottom-right corners of rectangles
    for x1 in range(n):
        for y1 in range(n):
            for x2 in range(x1, n):
                for y2 in range(y1, n):
                    if submatrix_sum(x1, y1, x2, y2) == a:
                        count += 1

    return count

